/*
 * variables.c — Logic variable registry for the Epilog inference engine.
 *
 * Variables are allocated per-query from a fixed-size VarRegistry.
 * Binding chains are walked with an explicit bounded loop (no recursion).
 * No heap allocation occurs after var_registry_init().
 *
 * JPL rules observed:
 *   Rule 1  — no goto, no setjmp/longjmp, no recursion.
 *   Rule 2  — every loop has a fixed upper bound (VAR_REGISTRY_CAPACITY).
 *   Rule 3  — no dynamic memory allocation after var_registry_init().
 *   Rule 4  — no function exceeds ~60 lines.
 *   Rule 5  — every parameter validated; every return value is meaningful.
 *   Rule 6  — preprocessor used only for include and simple constants.
 *   Rule 7  — pointer depth ≤ 1 in all operations.
 *   Rule 8  — compiled with -Wall -Wextra -Wpedantic.
 */

#include "../include/variables.h"

#include <assert.h>
#include <string.h>   /* memset, memcpy, strnlen */

/* -------------------------------------------------------------------------
 * Internal helpers
 * ------------------------------------------------------------------------- */

/*
 * entry_at — bounds-checked slot accessor.
 * Returns NULL when id is out of range; avoids pointer arithmetic elsewhere.
 */
static VarEntry *entry_at(VarRegistry *r, VarId id)
{
    uint32_t idx;

    assert(r != NULL);

    if (id == VAR_ID_INVALID || id < VAR_ID_MIN) {
        return NULL;
    }

    idx = id - VAR_ID_MIN;

    if (idx >= VAR_REGISTRY_CAPACITY || idx >= r->count) {
        return NULL;
    }

    return &r->entries[idx];
}

/* const variant for read-only callers */
static const VarEntry *entry_at_c(const VarRegistry *r, VarId id)
{
    uint32_t idx;

    assert(r != NULL);

    if (id == VAR_ID_INVALID || id < VAR_ID_MIN) {
        return NULL;
    }

    idx = id - VAR_ID_MIN;

    if (idx >= VAR_REGISTRY_CAPACITY || idx >= r->count) {
        return NULL;
    }

    return &r->entries[idx];
}

/* -------------------------------------------------------------------------
 * Public API
 * ------------------------------------------------------------------------- */

int var_registry_init(VarRegistry *r)
{
    if (r == NULL) {
        return -1;
    }
    memset(r, 0, sizeof(VarRegistry));
    return 0;
}

VarId var_alloc(VarRegistry *r, const char *name)
{
    VarEntry *slot;
    size_t    len;
    VarId     new_id;

    if (r == NULL || name == NULL) {
        return VAR_ID_INVALID;
    }

    if (r->count >= VAR_REGISTRY_CAPACITY) {
        return VAR_ID_INVALID;
    }

    len = strnlen(name, VAR_NAME_MAX_LEN + 1U);
    if (len > VAR_NAME_MAX_LEN) {
        return VAR_ID_INVALID;
    }

    new_id = (VarId)(r->count + VAR_ID_MIN);
    slot   = &r->entries[r->count];

    memset(slot, 0, sizeof(VarEntry));
    memcpy(slot->name, name, len);
    slot->name[len] = '\0';
    slot->tag       = TERM_UNBOUND;
    slot->id        = new_id;

    r->count++;
    return new_id;
}

int var_bind_atom(VarRegistry *r, VarId id, AtomId atom_id)
{
    VarEntry *e;

    if (r == NULL || atom_id == ATOM_ID_INVALID) {
        return -1;
    }

    e = entry_at(r, id);
    if (e == NULL) {
        return -1;
    }

    if (e->tag != TERM_UNBOUND) {
        return -1; /* already bound */
    }

    e->tag         = TERM_ATOM;
    e->value.atom_id = atom_id;
    return 0;
}

int var_bind_var(VarRegistry *r, VarId id, VarId other_id)
{
    VarEntry *e;

    if (r == NULL) {
        return -1;
    }

    /* Binding a variable to itself is a no-op, not an error. */
    if (id == other_id) {
        return 0;
    }

    e = entry_at(r, id);
    if (e == NULL) {
        return -1;
    }

    if (entry_at(r, other_id) == NULL) {
        return -1; /* other_id doesn't exist */
    }

    if (e->tag != TERM_UNBOUND) {
        return -1; /* already bound */
    }

    e->tag          = TERM_VAR;
    e->value.var_id = other_id;
    return 0;
}

WalkResult var_walk(const VarRegistry *r, VarId id)
{
    WalkResult     result;
    const VarEntry *e;
    VarId           current;
    uint32_t        steps;

    result.tag            = TERM_UNBOUND;
    result.value.var_id   = VAR_ID_INVALID;
    result.root_id        = VAR_ID_INVALID;

    if (r == NULL || id == VAR_ID_INVALID) {
        return result;
    }

    current = id;

    /*
     * Follow the binding chain. Bounded by VAR_REGISTRY_CAPACITY so the
     * loop is statically provable to terminate (JPL Rule 2).
     * No path compression — keeps pointer depth ≤ 1 (JPL Rule 7).
     */
    for (steps = 0U; steps < VAR_REGISTRY_CAPACITY; ++steps) {
        e = entry_at_c(r, current);
        if (e == NULL) {
            return result; /* dangling id — return invalid */
        }

        if (e->tag != TERM_VAR) {
            /* Reached an atom binding or an unbound variable — done. */
            result.tag      = e->tag;
            result.value    = e->value;
            result.root_id  = current;
            return result;
        }

        current = e->value.var_id;
    }

    /* Should be unreachable: cycle would require more entries than capacity. */
    assert(0);
    return result;
}

int var_reset(VarRegistry *r)
{
    if (r == NULL) {
        return -1;
    }
    memset(r, 0, sizeof(VarRegistry));
    return 0;
}

uint32_t var_count(const VarRegistry *r)
{
    if (r == NULL) {
        return 0U;
    }
    return r->count;
}

