/*
 * terms.h — Term representation for the Epilog inference engine.
 *
 * A Term is the universal data type of logic programming:
 *   - Atom       : an interned string constant  (e.g. alice, foo, [])
 *   - Var        : a logic variable             (e.g. X, _G42)
 *   - Compound   : a functor + fixed arity args (e.g. parent(alice,bob))
 *   - Int        : a machine integer            (e.g. 42)
 *
 * Storage strategy — no heap after init (JPL Rule 3):
 *   All terms live in a TermArena whose backing array is stack- or
 *   statically-allocated.  A TermRef is a 32-bit index into that arena.
 *   Compound arguments are stored as a contiguous run of TermRefs beginning
 *   at arg_start inside a shared ArgPool.
 *
 * JPL rules observed:
 *   Rule 1  — no goto, no recursion.
 *   Rule 2  — all loops and capacities statically bounded.
 *   Rule 3  — no malloc/free after arena init.
 *   Rule 5  — every function validates parameters, returns error codes.
 *   Rule 6  — preprocessor limited to includes + constants.
 *   Rule 7  — pointer depth ≤ 1 in public API.
 */

#ifndef EPILOG_TERMS_H
#define EPILOG_TERMS_H

#include <stdint.h>
#include <stddef.h>
#include "atoms.h"
#include "variables.h"

/* -------------------------------------------------------------------------
 * Capacities
 * ------------------------------------------------------------------------- */

#define TERM_ARENA_CAPACITY   8192U   /* max terms per arena          */
#define ARG_POOL_CAPACITY    32768U   /* max compound-arg slots total  */
#define TERM_MAX_ARITY          255U  /* max arguments for a compound  */
#define TERM_REF_INVALID          0U  /* sentinel — no valid term       */

/* -------------------------------------------------------------------------
 * TermRef — opaque index into a TermArena.
 * ------------------------------------------------------------------------- */

typedef uint32_t TermRef;

/* -------------------------------------------------------------------------
 * TermKind — discriminator tag.
 * ------------------------------------------------------------------------- */

typedef enum {
    TERM_KIND_ATOM     = 1,
    TERM_KIND_VAR      = 2,
    TERM_KIND_COMPOUND = 3,
    TERM_KIND_INT      = 4
} TermKind;

/* -------------------------------------------------------------------------
 * Term — one node stored inside the arena.
 * ------------------------------------------------------------------------- */

typedef struct {
    TermKind kind;
    union {
        AtomId   atom_id;    /* TERM_KIND_ATOM                           */
        VarId    var_id;     /* TERM_KIND_VAR                            */
        int32_t  int_val;    /* TERM_KIND_INT                            */
        struct {             /* TERM_KIND_COMPOUND                       */
            AtomId   functor;    /* functor name                         */
            uint8_t  arity;      /* number of arguments                  */
            uint32_t arg_start;  /* index into ArgPool                   */
        } compound;
    } data;
    TermRef ref; /* self-index; set on allocation */
} Term;

/* -------------------------------------------------------------------------
 * ArgPool — flat array of TermRefs used as compound arg storage.
 * ------------------------------------------------------------------------- */

typedef struct {
    TermRef  slots[ARG_POOL_CAPACITY];
    uint32_t count;
} ArgPool;

/* -------------------------------------------------------------------------
 * TermArena — owns all Term nodes for one inference session.
 * ------------------------------------------------------------------------- */

typedef struct {
    Term     nodes[TERM_ARENA_CAPACITY];
    uint32_t count;
    ArgPool  args;
} TermArena;

/* -------------------------------------------------------------------------
 * Public API
 * ------------------------------------------------------------------------- */

/* term_arena_init — zero-initialise before use. Returns 0 or -1. */
int term_arena_init(TermArena *a);

/* term_make_atom — allocate an atom term. Returns TERM_REF_INVALID on error. */
TermRef term_make_atom(TermArena *a, AtomId id);

/* term_make_var — allocate a variable term. Returns TERM_REF_INVALID on error. */
TermRef term_make_var(TermArena *a, VarId id);

/* term_make_int — allocate an integer term. Returns TERM_REF_INVALID on error. */
TermRef term_make_int(TermArena *a, int32_t val);

/*
 * term_make_compound — allocate a compound term.
 * args is an array of arity TermRefs for the arguments.
 * Returns TERM_REF_INVALID on error.
 */
TermRef term_make_compound(TermArena *a, AtomId functor, uint8_t arity,
                            const TermRef *args);

/*
 * term_get — retrieve a pointer to the Term for ref.
 * Returns NULL for TERM_REF_INVALID or out-of-range ref.
 * Pointer is valid only while the arena is not modified.
 */
const Term *term_get(const TermArena *a, TermRef ref);

/*
 * term_arg — get the n-th argument (0-based) of a compound term.
 * Returns TERM_REF_INVALID if ref is not a compound or n >= arity.
 */
TermRef term_arg(const TermArena *a, TermRef ref, uint8_t n);

/* term_kind — return the kind of a term; 0 if ref is invalid. */
TermKind term_kind(const TermArena *a, TermRef ref);

#endif /* EPILOG_TERMS_H */

/*
 * terms.c — Term arena implementation.
 *
 * JPL rules: no recursion, bounded loops, no post-init malloc, ≤1 ptr depth.
 */

#include "../include/terms.h"
#include <assert.h>
#include <string.h>

int term_arena_init(TermArena *a)
{
    if (a == NULL) {
        return -1;
    }
    memset(a, 0, sizeof(TermArena));
    return 0;
}

TermRef term_make_atom(TermArena *a, AtomId id)
{
    Term   *t;
    TermRef ref;

    if (a == NULL || id == ATOM_ID_INVALID) {
        return TERM_REF_INVALID;
    }
    if (a->count >= TERM_ARENA_CAPACITY) {
        return TERM_REF_INVALID;
    }

    ref = (TermRef)(a->count + 1U); /* 1-based; 0 == TERM_REF_INVALID */
    t   = &a->nodes[a->count];
    memset(t, 0, sizeof(Term));
    t->kind         = TERM_KIND_ATOM;
    t->data.atom_id = id;
    t->ref          = ref;
    a->count++;
    return ref;
}

TermRef term_make_var(TermArena *a, VarId id)
{
    Term   *t;
    TermRef ref;

    if (a == NULL || id == VAR_ID_INVALID) {
        return TERM_REF_INVALID;
    }
    if (a->count >= TERM_ARENA_CAPACITY) {
        return TERM_REF_INVALID;
    }

    ref = (TermRef)(a->count + 1U);
    t   = &a->nodes[a->count];
    memset(t, 0, sizeof(Term));
    t->kind        = TERM_KIND_VAR;
    t->data.var_id = id;
    t->ref         = ref;
    a->count++;
    return ref;
}

TermRef term_make_int(TermArena *a, int32_t val)
{
    Term   *t;
    TermRef ref;

    if (a == NULL) {
        return TERM_REF_INVALID;
    }
    if (a->count >= TERM_ARENA_CAPACITY) {
        return TERM_REF_INVALID;
    }

    ref = (TermRef)(a->count + 1U);
    t   = &a->nodes[a->count];
    memset(t, 0, sizeof(Term));
    t->kind          = TERM_KIND_INT;
    t->data.int_val  = val;
    t->ref           = ref;
    a->count++;
    return ref;
}

TermRef term_make_compound(TermArena *a, AtomId functor, uint8_t arity,
                            const TermRef *args)
{
    Term    *t;
    TermRef  ref;
    uint8_t  i;

    if (a == NULL || functor == ATOM_ID_INVALID) {
        return TERM_REF_INVALID;
    }
    if (arity > TERM_MAX_ARITY) {
        return TERM_REF_INVALID;
    }
    if (arity > 0U && args == NULL) {
        return TERM_REF_INVALID;
    }
    if (a->count >= TERM_ARENA_CAPACITY) {
        return TERM_REF_INVALID;
    }
    if (a->args.count + (uint32_t)arity > ARG_POOL_CAPACITY) {
        return TERM_REF_INVALID;
    }

    ref = (TermRef)(a->count + 1U);
    t   = &a->nodes[a->count];
    memset(t, 0, sizeof(Term));
    t->kind                  = TERM_KIND_COMPOUND;
    t->data.compound.functor   = functor;
    t->data.compound.arity     = arity;
    t->data.compound.arg_start = a->args.count;
    t->ref                   = ref;

    for (i = 0U; i < arity; ++i) {
        assert(a->args.count < ARG_POOL_CAPACITY);
        a->args.slots[a->args.count] = args[i];
        a->args.count++;
    }

    a->count++;
    return ref;
}

const Term *term_get(const TermArena *a, TermRef ref)
{
    uint32_t idx;

    if (a == NULL || ref == TERM_REF_INVALID) {
        return NULL;
    }
    idx = ref - 1U;
    if (idx >= a->count) {
        return NULL;
    }
    return &a->nodes[idx];
}

TermRef term_arg(const TermArena *a, TermRef ref, uint8_t n)
{
    const Term *t;
    uint32_t    pool_idx;

    t = term_get(a, ref);
    if (t == NULL || t->kind != TERM_KIND_COMPOUND) {
        return TERM_REF_INVALID;
    }
    if (n >= t->data.compound.arity) {
        return TERM_REF_INVALID;
    }

    pool_idx = t->data.compound.arg_start + (uint32_t)n;
    assert(pool_idx < ARG_POOL_CAPACITY);
    return a->args.slots[pool_idx];
}

TermKind term_kind(const TermArena *a, TermRef ref)
{
    const Term *t = term_get(a, ref);
    if (t == NULL) {
        return (TermKind)0;
    }
    return t->kind;
}

/*
 * parser.h — Clause and query parser for Epilog.
 *
 * Consumes a TokenList (produced by lexer.h) and populates a TermArena with
 * the parsed terms.  Results are expressed as ParsedClause / ParsedQuery
 * structs that hold TermRefs into the arena.
 *
 * Grammar (simplified):
 *   program   ::= clause* EOF
 *   clause    ::= term '.'                    -- fact
 *               | term ':-' term_list '.'     -- rule
 *   query     ::= '?-' term_list '.'
 *   term_list ::= term (',' term)*
 *   term      ::= atom
 *               | variable
 *               | integer
 *               | atom '(' term_list ')'      -- compound
 *               | term op term                -- operator (= \= only for 0.1)
 *               | '!' | 'true' | 'fail'
 *
 * No heap allocation; caller owns arena and TokenList.
 *
 * JPL rules: no recursion (iterative descent with explicit stack),
 *            bounded loops, no post-init malloc.
 */

#ifndef EPILOG_PARSER_H
#define EPILOG_PARSER_H

#include <stdint.h>
#include "lexer.h"
#include "terms.h"
#include "atoms.h"
#include "variables.h"

#define PARSER_MAX_BODY_GOALS   256U  /* max goals in a clause body    */
#define PARSER_MAX_CLAUSES      512U  /* max clauses in one parse pass */

/* -------------------------------------------------------------------------
 * ParsedClause
 * ------------------------------------------------------------------------- */

typedef struct {
    TermRef head;                              /* always set           */
    TermRef body[PARSER_MAX_BODY_GOALS];       /* goals; 0 == fact     */
    uint32_t body_len;
} ParsedClause;

/* -------------------------------------------------------------------------
 * ParsedQuery
 * ------------------------------------------------------------------------- */

typedef struct {
    TermRef goals[PARSER_MAX_BODY_GOALS];
    uint32_t goal_count;
} ParsedQuery;

/* -------------------------------------------------------------------------
 * ParseResult — returned by every parse function.
 * ------------------------------------------------------------------------- */

typedef enum {
    PARSE_OK = 0,
    PARSE_EOF,           /* clean end of token stream              */
    PARSE_ERR_SYNTAX,    /* unexpected token                       */
    PARSE_ERR_OVERFLOW,  /* clause/body too large, arena full, etc */
    PARSE_ERR_ARGS       /* NULL pointer passed                    */
} ParseResult;

/* -------------------------------------------------------------------------
 * Parser state — initialise with parser_init, then call parse_* functions.
 * ------------------------------------------------------------------------- */

typedef struct {
    const TokenList *tokens;
    uint32_t         pos;       /* current read position */
    TermArena       *arena;
    AtomTable       *atoms;
    VarRegistry     *vars;      /* reset per clause */
    char             error_msg[128];
} Parser;

/* parser_init — bind a parser to its inputs. Returns 0 or -1. */
int parser_init(Parser *p, const TokenList *tokens, TermArena *arena,
                AtomTable *atoms, VarRegistry *vars);

/*
 * parser_next_clause — parse one clause from the token stream.
 * Advances p->pos past the terminating '.'.
 * Returns PARSE_OK, PARSE_EOF, or an error code.
 */
ParseResult parser_next_clause(Parser *p, ParsedClause *out);

/*
 * parser_query — parse a '?- goals .' query.
 * Expects the leading TOK_QUERY to be the current token.
 */
ParseResult parser_query(Parser *p, ParsedQuery *out);

#endif /* EPILOG_PARSER_H */

/*
 * database.h — Clause database for the Epilog inference engine.
 *
 * Stores asserted clauses indexed by functor/arity for fast lookup.
 * All storage is pre-allocated in a Database struct (no post-init malloc).
 *
 * Each predicate (functor + arity pair) owns a contiguous run of ClauseIds
 * inside a shared ClausePool.  A PredIndex maps functor/arity → run.
 *
 * JPL rules: no recursion, bounded capacities, no post-init malloc.
 */

#ifndef EPILOG_DATABASE_H
#define EPILOG_DATABASE_H

#include <stdint.h>
#include "atoms.h"
#include "terms.h"
#include "parser.h"

#define DB_MAX_PREDICATES   512U
#define DB_MAX_CLAUSES     4096U
#define DB_MAX_BODY_GOALS   PARSER_MAX_BODY_GOALS

/* -------------------------------------------------------------------------
 * Stored clause
 * ------------------------------------------------------------------------- */

typedef uint32_t ClauseId;
#define CLAUSE_ID_INVALID  0U

typedef struct {
    TermRef  head;
    TermRef  body[DB_MAX_BODY_GOALS];
    uint32_t body_len;
    ClauseId id;
} StoredClause;

/* -------------------------------------------------------------------------
 * Predicate index entry
 * ------------------------------------------------------------------------- */

typedef struct {
    AtomId   functor;
    uint8_t  arity;
    uint32_t first;   /* index into Database.clauses[]  */
    uint32_t count;   /* number of clauses for this pred */
} PredEntry;

/* -------------------------------------------------------------------------
 * Database
 * ------------------------------------------------------------------------- */

typedef struct {
    StoredClause clauses[DB_MAX_CLAUSES];
    uint32_t     clause_count;

    PredEntry    preds[DB_MAX_PREDICATES];
    uint32_t     pred_count;
} Database;

/* -------------------------------------------------------------------------
 * Public API
 * ------------------------------------------------------------------------- */

/* db_init — zero-initialise before use. Returns 0 or -1. */
int db_init(Database *db);

/*
 * db_assert_last — add a clause at the end of its predicate's clause list.
 * Returns 0 on success, -1 on capacity overflow or bad args.
 */
int db_assert_last(Database *db, const ParsedClause *clause, TermArena *arena);

/*
 * db_retract_first — remove the first matching clause for head.
 * Matching is by functor and arity only (caller handles unification).
 * Returns 0 on success, -1 if not found.
 */
int db_retract_first(Database *db, AtomId functor, uint8_t arity);

/*
 * db_get_pred — find the PredEntry for functor/arity.
 * Returns NULL if no clauses are stored for that predicate.
 */
const PredEntry *db_get_pred(const Database *db, AtomId functor, uint8_t arity);

/*
 * db_get_clause — retrieve a clause by its index in the clause pool.
 * Returns NULL for out-of-range index.
 */
const StoredClause *db_get_clause(const Database *db, uint32_t idx);

#endif /* EPILOG_DATABASE_H */

/*
 * unifier.h — Robinson unification for the Epilog inference engine.
 *
 * Unification operates on a Trail + VarRegistry pair.
 * The Trail records every variable bound during one resolution step so that
 * backtracking can undo all bindings in O(trail_length) time.
 *
 * No occurs check by default (standard Prolog semantics).
 *
 * JPL rules: no recursion (iterative with explicit work stack),
 *            bounded loops, no post-init malloc.
 */

#ifndef EPILOG_UNIFIER_H
#define EPILOG_UNIFIER_H

#include <stdint.h>
#include "terms.h"
#include "variables.h"

#define TRAIL_CAPACITY      4096U   /* max bindings recorded per query  */
#define UNIFY_STACK_CAPACITY 512U   /* work stack depth for unification  */

/* -------------------------------------------------------------------------
 * Trail — records variable bindings for backtrack undo.
 * ------------------------------------------------------------------------- */

typedef struct {
    VarId    bound[TRAIL_CAPACITY];
    uint32_t top;
} Trail;

/* trail_init — zero-initialise. Returns 0 or -1. */
int trail_init(Trail *t);

/* trail_mark — return current trail top (used as a backtrack checkpoint). */
uint32_t trail_mark(const Trail *t);

/*
 * trail_undo — unbind all variables pushed since mark.
 * Resets each VarEntry to TERM_UNBOUND.
 */
void trail_undo(Trail *t, VarRegistry *vars, uint32_t mark);

/* -------------------------------------------------------------------------
 * Unification
 * ------------------------------------------------------------------------- */

/*
 * unify — attempt to unify terms a and b under the current bindings in vars.
 * New bindings are recorded on trail.
 * Returns 1 on success (terms unified), 0 on failure (terms clash).
 * On failure, bindings made during this call are NOT automatically undone;
 * call trail_undo(trail, vars, mark) where mark was taken before the call.
 */
int unify(TermRef a, TermRef b,
          const TermArena *arena, VarRegistry *vars, Trail *trail);

/*
 * deref — follow variable bindings to the canonical term for ref.
 * Returns the TermRef of the root (atom, int, compound, or unbound var).
 * Pure read — does not modify vars.
 */
TermRef deref(TermRef ref, const TermArena *arena, const VarRegistry *vars);

#endif /* EPILOG_UNIFIER_H */

/*
 * solver.h — Backtracking resolution engine for Epilog.
 *
 * The solver executes a list of goals against a Database using SLD resolution.
 * It is depth-first and left-to-right, matching standard Prolog semantics.
 *
 * Execution model:
 *   - A ChoicePoint records the state at each point where multiple clauses
 *     could match, so backtracking can restore and try the next clause.
 *   - The goal stack holds remaining goals for the current branch.
 *   - No recursion: the main loop pops goals and pushes new ones iteratively.
 *
 * The solver calls a SolutionCallback for each solution found.  The callback
 * returns SOLVE_NEXT to request more solutions or SOLVE_STOP to halt search.
 *
 * JPL rules: no recursion, bounded stacks, no post-init malloc.
 */

#ifndef EPILOG_SOLVER_H
#define EPILOG_SOLVER_H

#include <stdint.h>
#include "terms.h"
#include "variables.h"
#include "unifier.h"
#include "database.h"
#include "atoms.h"

#define GOAL_STACK_CAPACITY    512U
#define CHOICE_STACK_CAPACITY  256U
#define SOLVE_VAR_BLOCK       1024U  /* vars allocated per frame copy  */

/* -------------------------------------------------------------------------
 * SolveSignal — callback return value.
 * ------------------------------------------------------------------------- */

typedef enum {
    SOLVE_NEXT = 0,  /* continue search, yield more solutions */
    SOLVE_STOP = 1   /* halt search after this solution       */
} SolveSignal;

/* -------------------------------------------------------------------------
 * SolverEnv — everything the solver needs, passed by pointer.
 * ------------------------------------------------------------------------- */

typedef struct {
    TermArena   *arena;
    VarRegistry *vars;
    Trail        trail;
    AtomTable   *atoms;
    Database    *db;
} SolverEnv;

/* -------------------------------------------------------------------------
 * SolutionCallback
 *
 * Called once per solution. env carries the current (bound) state.
 * goals_in is the original query goal array; goal_count its length.
 * Return SOLVE_NEXT or SOLVE_STOP.
 * ------------------------------------------------------------------------- */

typedef SolveSignal (*SolutionCallback)(SolverEnv *env,
                                        const TermRef *goals_in,
                                        uint32_t goal_count,
                                        void *userdata);

/* -------------------------------------------------------------------------
 * Public API
 * ------------------------------------------------------------------------- */

/* solver_env_init — zero-initialise env. Returns 0 or -1. */
int solver_env_init(SolverEnv *env, TermArena *arena, VarRegistry *vars,
                    AtomTable *atoms, Database *db);

/*
 * solve — run goals[0..goal_count-1] against env->db.
 * Calls cb for each solution found.
 * Returns the number of solutions found (0 if none).
 */
uint32_t solve(SolverEnv *env, const TermRef *goals, uint32_t goal_count,
               SolutionCallback cb, void *userdata);

#endif /* EPILOG_SOLVER_H */

/*
 * builtins.h — Built-in predicate dispatch for Epilog 0.1.
 *
 * Built-ins handled:
 *   true/0      — always succeeds
 *   fail/0      — always fails
 *   !/0         — cut (signals parent choice-point removal)
 *   =/2         — unification
 *   \=/2        — non-unification
 *   write/1     — print a term to stdout
 *   nl/0        — print newline
 *   assert/1    — add clause to database (assertz semantics)
 *   retract/1   — remove first matching clause
 *
 * Each built-in follows the BuiltinFn signature.
 * builtin_lookup returns NULL for unknown functors so the solver falls
 * through to user-defined clause resolution.
 */

#ifndef EPILOG_BUILTINS_H
