#include <stdint.h>
#include "terms.h"
#include "atoms.h"
#include "variables.h"
#include "unifier.h"
#include "database.h"
#include "solver.h"

/* -------------------------------------------------------------------------
 * BuiltinResult — what a built-in tells the solver.
 * ------------------------------------------------------------------------- */

typedef enum {
    BUILTIN_SUCCEED = 0,   /* goal succeeded; continue            */
    BUILTIN_FAIL    = 1,   /* goal failed; backtrack              */
    BUILTIN_CUT     = 2,   /* cut; discard parent choice points   */
    BUILTIN_ERROR   = 3    /* runtime error; halt with message    */
} BuiltinResult;

/* -------------------------------------------------------------------------
 * BuiltinFn — function pointer type for all built-in implementations.
 * ------------------------------------------------------------------------- */

typedef BuiltinResult (*BuiltinFn)(TermRef goal, SolverEnv *env);

/* -------------------------------------------------------------------------
 * Public API
 * ------------------------------------------------------------------------- */

/*
 * builtin_lookup — return the BuiltinFn for functor/arity, or NULL.
 * Called by the solver before attempting clause resolution.
 */
BuiltinFn builtin_lookup(AtomId functor, uint8_t arity, const AtomTable *atoms);

/*
 * term_write — print a term to stdout following standard Prolog notation.
 * Used by write/1 and also by the REPL to display solutions.
 * Returns 0 on success, -1 on bad args.
