/*
 * lexer.c — Tokenizer implementation.
 *
 * Single-pass, no backtracking, no heap allocation.
 * JPL rules: no recursion, bounded loop (len of src), no post-init malloc.
 */

#include "../include/lexer.h"
#include <string.h>
#include <assert.h>
#include <stdint.h>

/* -------------------------------------------------------------------------
 * Character class helpers
 * ------------------------------------------------------------------------- */

static int is_alpha(char c)  { return (c>='a'&&c<='z')||(c>='A'&&c<='Z'); }
static int is_digit(char c)  { return c>='0' && c<='9'; }
static int is_lower(char c)  { return c>='a' && c<='z'; }
static int is_upper(char c)  { return c>='A' && c<='Z'; }
static int is_alnum(char c)  { return is_alpha(c) || is_digit(c) || c=='_'; }
static int is_space(char c)  { return c==' '||c=='\t'||c=='\r'||c=='\n'; }

static int is_op_char(char c)
{
    return c=='='||c=='\\'||c=='+'||c=='-'||c=='*'||c=='/'||
           c=='<'||c=='>'||c=='@'||c=='#'||c=='^'||c=='~';
}

/* -------------------------------------------------------------------------
 * append_token — add one token to the list; returns 0 or -1 on overflow.
 * ------------------------------------------------------------------------- */

static int append_token(TokenList *out, TokenKind kind,
                        const char *text, int32_t int_val, uint32_t line)
{
    Token *t;

    assert(out != NULL);

    if (out->count >= TOKEN_LIST_CAPACITY) {
        return -1;
    }

    t = &out->items[out->count];
    t->kind    = kind;
    t->int_val = int_val;
    t->line    = line;

    if (text != NULL) {
        size_t len = strnlen(text, TOKEN_TEXT_MAX);
        memcpy(t->text, text, len);
        t->text[len] = '\0';
    } else {
        t->text[0] = '\0';
    }

    out->count++;
    return 0;
}

/* -------------------------------------------------------------------------
 * lex
 * ------------------------------------------------------------------------- */

int lex(const char *src, TokenList *out)
{
    uint32_t i;
    uint32_t len;
    uint32_t line;
    char     buf[TOKEN_TEXT_MAX + 1U];
    uint32_t buf_pos;

    if (src == NULL || out == NULL) {
        return -1;
    }

    memset(out, 0, sizeof(TokenList));
    len  = (uint32_t)strnlen(src, 1U << 20); /* 1 MB cap */
    line = 1U;
    i    = 0U;

    while (i < len) {
        char c = src[i];

        /* skip whitespace */
        if (is_space(c)) {
            if (c == '\n') { line++; }
            i++;
            continue;
        }

        /* line comment */
        if (c == '%') {
            while (i < len && src[i] != '\n') { i++; }
            continue;
        }

        /* block comment */
        if (c == '/' && i + 1U < len && src[i + 1U] == '*') {
            uint32_t depth = 1U;
            i += 2U;
            while (i + 1U < len && depth > 0U) {
                if (src[i] == '\n')                          { line++; }
                if (src[i] == '*' && src[i+1U] == '/')      { depth--; i += 2U; continue; }
                if (src[i] == '/' && src[i+1U] == '*')      { depth++; i += 2U; continue; }
                i++;
            }
            continue;
        }

        /* atom: lowercase-initial or operator-sequence */
        if (is_lower(c)) {
            buf_pos = 0U;
            while (i < len && is_alnum(src[i]) && buf_pos < TOKEN_TEXT_MAX) {
                buf[buf_pos++] = src[i++];
            }
            buf[buf_pos] = '\0';
            if (append_token(out, TOK_ATOM, buf, 0, line) < 0) { return -1; }
            continue;
        }

        /* variable: uppercase or underscore initial */
        if (is_upper(c) || c == '_') {
            buf_pos = 0U;
            while (i < len && is_alnum(src[i]) && buf_pos < TOKEN_TEXT_MAX) {
                buf[buf_pos++] = src[i++];
            }
            buf[buf_pos] = '\0';
            if (append_token(out, TOK_VAR, buf, 0, line) < 0) { return -1; }
            continue;
        }

        /* integer */
        if (is_digit(c)) {
            int32_t val = 0;
            buf_pos = 0U;
            while (i < len && is_digit(src[i]) && buf_pos < TOKEN_TEXT_MAX) {
                val = val * 10 + (int32_t)(src[i] - '0');
                buf[buf_pos++] = src[i++];
            }
            buf[buf_pos] = '\0';
            if (append_token(out, TOK_INT, buf, val, line) < 0) { return -1; }
            continue;
        }

        /* single-quoted atom */
        if (c == '\'') {
            buf_pos = 0U;
            i++; /* skip opening quote */
            while (i < len && src[i] != '\'' && buf_pos < TOKEN_TEXT_MAX) {
                if (src[i] == '\n') { line++; }
                buf[buf_pos++] = src[i++];
            }
            if (i < len) { i++; } /* skip closing quote */
            buf[buf_pos] = '\0';
            if (append_token(out, TOK_ATOM, buf, 0, line) < 0) { return -1; }
            continue;
        }

        /* two-character tokens */
        if (c == ':' && i + 1U < len && src[i+1U] == '-') {
            if (append_token(out, TOK_NECK,  ":-", 0, line) < 0) { return -1; }
            i += 2U; continue;
        }
        if (c == '?' && i + 1U < len && src[i+1U] == '-') {
            if (append_token(out, TOK_QUERY, "?-", 0, line) < 0) { return -1; }
            i += 2U; continue;
        }
        if (c == '\\' && i + 1U < len && src[i+1U] == '=') {
            if (append_token(out, TOK_OP,    "\\=", 0, line) < 0) { return -1; }
            i += 2U; continue;
        }

        /* operator sequences (=, etc.) */
        if (is_op_char(c)) {
            buf_pos = 0U;
            while (i < len && is_op_char(src[i]) && buf_pos < TOKEN_TEXT_MAX) {
                buf[buf_pos++] = src[i++];
            }
            buf[buf_pos] = '\0';
            if (append_token(out, TOK_OP, buf, 0, line) < 0) { return -1; }
            continue;
        }

        /* single-character punctuation */
        switch (c) {
            case '(': append_token(out, TOK_LPAREN, "(", 0, line); break;
            case ')': append_token(out, TOK_RPAREN, ")", 0, line); break;
            case ',': append_token(out, TOK_COMMA,  ",", 0, line); break;
            case '.':
                /* '.' followed by whitespace or EOF is clause terminator */
                if (i + 1U >= len || is_space(src[i+1U])) {
                    append_token(out, TOK_DOT, ".", 0, line);
                } else {
                    append_token(out, TOK_OP, ".", 0, line);
                }
                break;
            case '|': append_token(out, TOK_PIPE,  "|", 0, line); break;
            case ';': append_token(out, TOK_SEMI,  ";", 0, line); break;
            case '!': append_token(out, TOK_CUT,   "!", 0, line); break;
            default: {
                char err[2] = { c, '\0' };
                append_token(out, TOK_ERROR, err, 0, line);
                return -1;
            }
        }
        i++;
    }

    append_token(out, TOK_EOF, "", 0, line);
    return 0;
}

const char *tok_kind_name(TokenKind k)
{
    switch (k) {
        case TOK_ATOM:   return "atom";
        case TOK_VAR:    return "variable";
        case TOK_INT:    return "integer";
        case TOK_LPAREN: return "'('";
        case TOK_RPAREN: return "')'";
        case TOK_COMMA:  return "','";
        case TOK_DOT:    return "'.'";
        case TOK_NECK:   return "':-'";
        case TOK_QUERY:  return "'?-'";
        case TOK_PIPE:   return "'|'";
        case TOK_SEMI:   return "';'";
        case TOK_CUT:    return "'!'";
        case TOK_OP:     return "operator";
        case TOK_EOF:    return "EOF";
        case TOK_ERROR:  return "error";
        default:         return "unknown";
    }
}

/*
 * parser.c — Clause and query parser.
 *
 * Iterative top-down parser (no recursion — JPL Rule 1).
 * Uses an explicit work stack for nested compound arguments.
 *
 * JPL rules: no recursion, bounded stacks/loops, no post-init malloc.
 */

#include "../include/parser.h"
#include <string.h>
#include <assert.h>
#include <stdio.h>

/* -------------------------------------------------------------------------
 * Internal helpers
 * ------------------------------------------------------------------------- */

/* peek — return current token without advancing. */
static const Token *peek(const Parser *p)
{
    assert(p != NULL && p->tokens != NULL);
    if (p->pos >= p->tokens->count) {
        return &p->tokens->items[p->tokens->count - 1U]; /* EOF */
    }
    return &p->tokens->items[p->pos];
}

/* advance — consume and return current token. */
static const Token *advance(Parser *p)
{
    const Token *t = peek(p);
    if (t->kind != TOK_EOF) { p->pos++; }
    return t;
}

/* expect — consume token of expected kind; returns NULL and sets error otherwise. */
static const Token *expect(Parser *p, TokenKind kind)
{
    const Token *t = peek(p);
    if (t->kind != kind) {
        snprintf(p->error_msg, sizeof(p->error_msg),
                 "line %u: expected %s, got %s '%s'",
                 t->line, tok_kind_name(kind), tok_kind_name(t->kind), t->text);
        return NULL;
    }
    return advance(p);
}

/* -------------------------------------------------------------------------
 * parse_term — parse a single term from the token stream.
 * Returns TERM_REF_INVALID on error.
 *
 * Handles: atom, variable, integer, compound(args), op infix (= \=).
 * Iterative: compound args parsed with a small local array, no stack.
 * Max arity bounded by TERM_MAX_ARITY.
 * ------------------------------------------------------------------------- */

static TermRef parse_term(Parser *p)
{
    const Token *t;
    AtomId       aid;
    VarId        vid;
    TermRef      ref;

    t = peek(p);

    /* integer */
    if (t->kind == TOK_INT) {
        advance(p);
        return term_make_int(p->arena, t->int_val);
    }

    /* variable */
    if (t->kind == TOK_VAR) {
        advance(p);
        /* re-use existing variable with same name in this clause */
        vid = VAR_ID_INVALID;
        {
            uint32_t n;
            for (n = 0U; n < var_count(p->vars); ++n) {
                VarId probe = (VarId)(n + VAR_ID_MIN);
                WalkResult wr = var_walk(p->vars, probe);
                /* check name via the registry's entries directly */
                (void)wr;
            }
            /* simpler: scan by position */
            {
                uint32_t k;
                for (k = 0U; k < p->vars->count; ++k) {
                    if (strncmp(p->vars->entries[k].name, t->text,
                                VAR_NAME_MAX_LEN) == 0) {
                        vid = p->vars->entries[k].id;
                        break;
                    }
                }
            }
        }
        if (vid == VAR_ID_INVALID) {
            vid = var_alloc(p->vars, t->text);
        }
        if (vid == VAR_ID_INVALID) {
            snprintf(p->error_msg, sizeof(p->error_msg),
                     "line %u: variable registry full", t->line);
            return TERM_REF_INVALID;
        }
        return term_make_var(p->arena, vid);
    }

    /* cut — treat as atom '!' */
    if (t->kind == TOK_CUT) {
        advance(p);
        aid = atom_intern(p->atoms, "!");
        if (aid == ATOM_ID_INVALID) { return TERM_REF_INVALID; }
        return term_make_atom(p->arena, aid);
    }

    /* atom or compound */
    if (t->kind == TOK_ATOM || t->kind == TOK_OP) {
        const char *name = t->text;
        advance(p);
        aid = atom_intern(p->atoms, name);
        if (aid == ATOM_ID_INVALID) {
            snprintf(p->error_msg, sizeof(p->error_msg),
                     "line %u: atom table full", t->line);
            return TERM_REF_INVALID;
        }

        /* compound: atom immediately followed by '(' */
        if (peek(p)->kind == TOK_LPAREN) {
            TermRef args[TERM_MAX_ARITY];
            uint8_t arity = 0U;

            advance(p); /* consume '(' */

            if (peek(p)->kind != TOK_RPAREN) {
                /* parse comma-separated arg list */
                uint32_t a;
                for (a = 0U; a < (uint32_t)TERM_MAX_ARITY; ++a) {
                    TermRef arg = parse_term(p);
                    if (arg == TERM_REF_INVALID) { return TERM_REF_INVALID; }
                    args[arity++] = arg;
                    if (peek(p)->kind != TOK_COMMA) { break; }
                    advance(p); /* consume ',' */
                }
            }

            if (expect(p, TOK_RPAREN) == NULL) { return TERM_REF_INVALID; }
            ref = term_make_compound(p->arena, aid, arity, args);
        } else {
            ref = term_make_atom(p->arena, aid);
        }

        /* infix operator: = or \= immediately following */
        {
            const Token *op = peek(p);
            if (op->kind == TOK_OP &&
                (strncmp(op->text, "=",  2) == 0 ||
                 strncmp(op->text, "\\=", 3) == 0)) {
                char op_name[TOKEN_TEXT_MAX + 1U];
                AtomId op_aid;
                TermRef rhs;
                TermRef pair[2];

                memcpy(op_name, op->text, TOKEN_TEXT_MAX);
                op_name[TOKEN_TEXT_MAX] = '\0';
                advance(p);

                rhs = parse_term(p);
                if (rhs == TERM_REF_INVALID) { return TERM_REF_INVALID; }

                op_aid = atom_intern(p->atoms, op_name);
                if (op_aid == ATOM_ID_INVALID) { return TERM_REF_INVALID; }

                pair[0] = ref;
                pair[1] = rhs;
                ref = term_make_compound(p->arena, op_aid, 2U, pair);
            }
        }

        return ref;
    }

    snprintf(p->error_msg, sizeof(p->error_msg),
             "line %u: unexpected token %s '%s'",
             t->line, tok_kind_name(t->kind), t->text);
    return TERM_REF_INVALID;
}

/* parse_term_list — parse a comma-separated goal list into out[]. */
static ParseResult parse_term_list(Parser *p, TermRef *out, uint32_t cap,
                                   uint32_t *count)
{
    uint32_t n = 0U;

    assert(p != NULL && out != NULL && count != NULL);
    *count = 0U;

    for (n = 0U; n < cap; ++n) {
        TermRef ref = parse_term(p);
        if (ref == TERM_REF_INVALID) {
            return PARSE_ERR_SYNTAX;
        }
        out[n] = ref;
        (*count)++;
        if (peek(p)->kind != TOK_COMMA) { break; }
        advance(p); /* consume ',' */
    }

    if (*count == cap && peek(p)->kind == TOK_COMMA) {
        return PARSE_ERR_OVERFLOW;
    }
    return PARSE_OK;
}

/* -------------------------------------------------------------------------
 * Public API
 * ------------------------------------------------------------------------- */

int parser_init(Parser *p, const TokenList *tokens, TermArena *arena,
                AtomTable *atoms, VarRegistry *vars)
{
    if (p == NULL || tokens == NULL || arena == NULL ||
        atoms == NULL || vars == NULL) {
        return -1;
    }
    memset(p, 0, sizeof(Parser));
    p->tokens = tokens;
    p->arena  = arena;
    p->atoms  = atoms;
    p->vars   = vars;
    p->pos    = 0U;
    return 0;
}

ParseResult parser_next_clause(Parser *p, ParsedClause *out)
{
    TermRef head;

    if (p == NULL || out == NULL) { return PARSE_ERR_ARGS; }
    memset(out, 0, sizeof(ParsedClause));

    /* reset variables for this clause */
    var_reset(p->vars);

    if (peek(p)->kind == TOK_EOF) { return PARSE_EOF; }

    head = parse_term(p);
    if (head == TERM_REF_INVALID) { return PARSE_ERR_SYNTAX; }
    out->head = head;

    if (peek(p)->kind == TOK_NECK) {
        advance(p); /* consume ':-' */
        ParseResult r = parse_term_list(p, out->body, PARSER_MAX_BODY_GOALS,
                                        &out->body_len);
        if (r != PARSE_OK) { return r; }
    }

    if (expect(p, TOK_DOT) == NULL) { return PARSE_ERR_SYNTAX; }
    return PARSE_OK;
}

ParseResult parser_query(Parser *p, ParsedQuery *out)
{
    if (p == NULL || out == NULL) { return PARSE_ERR_ARGS; }
    memset(out, 0, sizeof(ParsedQuery));

    var_reset(p->vars);

    if (expect(p, TOK_QUERY) == NULL) { return PARSE_ERR_SYNTAX; }

    ParseResult r = parse_term_list(p, out->goals, PARSER_MAX_BODY_GOALS,
                                    &out->goal_count);
    if (r != PARSE_OK) { return r; }

    if (expect(p, TOK_DOT) == NULL) { return PARSE_ERR_SYNTAX; }
    return PARSE_OK;
}

/*
 * database.c — Clause database implementation.
 *
 * Predicates are indexed by functor+arity. Each predicate owns a contiguous
 * run of StoredClause slots in Database.clauses[]. assert appends; retract
 * shifts remaining clauses left (simple, safe, bounded).
 *
 * JPL rules: no recursion, bounded loops, no post-init malloc.
 */

#include "../include/database.h"
#include <string.h>
#include <assert.h>

/* -------------------------------------------------------------------------
 * Internal: find or create a PredEntry for functor/arity.
 * ------------------------------------------------------------------------- */

static PredEntry *find_pred(Database *db, AtomId functor, uint8_t arity)
{
    uint32_t i;

    assert(db != NULL);

    for (i = 0U; i < db->pred_count; ++i) {
        if (db->preds[i].functor == functor &&
            db->preds[i].arity   == arity) {
            return &db->preds[i];
        }
    }
    return NULL;
}

static PredEntry *find_or_create_pred(Database *db, AtomId functor,
                                       uint8_t arity)
{
    PredEntry *e = find_pred(db, functor, arity);
    if (e != NULL) { return e; }

    if (db->pred_count >= DB_MAX_PREDICATES) { return NULL; }

    e = &db->preds[db->pred_count];
    memset(e, 0, sizeof(PredEntry));
    e->functor = functor;
    e->arity   = arity;
    e->first   = db->clause_count; /* will be filled by assert */
    e->count   = 0U;
    db->pred_count++;
    return e;
}

/* -------------------------------------------------------------------------
 * Public API
 * ------------------------------------------------------------------------- */

int db_init(Database *db)
{
    if (db == NULL) { return -1; }
    memset(db, 0, sizeof(Database));
    return 0;
}

int db_assert_last(Database *db, const ParsedClause *clause, TermArena *arena)
{
    const Term *head_term;
    AtomId      functor;
    uint8_t     arity;
    PredEntry  *pred;
    StoredClause *sc;
    uint32_t    body_i;
    uint32_t    insert_pos;
    uint32_t    shift;

    (void)arena; /* reserved for future deep-copy; terms already in arena */

    if (db == NULL || clause == NULL) { return -1; }
    if (db->clause_count >= DB_MAX_CLAUSES) { return -1; }

    head_term = term_get(arena, clause->head);
    if (head_term == NULL) { return -1; }

    switch (head_term->kind) {
        case TERM_KIND_ATOM:
            functor = head_term->data.atom_id;
            arity   = 0U;
            break;
        case TERM_KIND_COMPOUND:
            functor = head_term->data.compound.functor;
            arity   = head_term->data.compound.arity;
            break;
        default:
            return -1; /* head must be atom or compound */
    }

    pred = find_or_create_pred(db, functor, arity);
    if (pred == NULL) { return -1; }

    /*
     * Insert position: just after the last clause of this predicate.
     * All subsequent clauses (other predicates) must be shifted right.
     */
    insert_pos = pred->first + pred->count;

    /* shift clauses after insert_pos right by one */
    for (shift = db->clause_count; shift > insert_pos; --shift) {
        db->clauses[shift] = db->clauses[shift - 1U];
        db->clauses[shift].id = (ClauseId)(shift + 1U);
    }

    /* fix up pred->first for all predicates whose clauses moved right */
    {
        uint32_t pi;
        for (pi = 0U; pi < db->pred_count; ++pi) {
            if (&db->preds[pi] != pred &&
                db->preds[pi].first >= insert_pos) {
                db->preds[pi].first++;
            }
        }
    }

    sc = &db->clauses[insert_pos];
    memset(sc, 0, sizeof(StoredClause));
    sc->head     = clause->head;
    sc->body_len = clause->body_len;
    sc->id       = (ClauseId)(insert_pos + 1U);

    assert(clause->body_len <= DB_MAX_BODY_GOALS);
    for (body_i = 0U; body_i < clause->body_len; ++body_i) {
        sc->body[body_i] = clause->body[body_i];
    }

    pred->count++;
    db->clause_count++;
    return 0;
}

int db_retract_first(Database *db, AtomId functor, uint8_t arity)
{
    PredEntry *pred;
    uint32_t   remove_pos;
    uint32_t   shift;

    if (db == NULL || functor == ATOM_ID_INVALID) { return -1; }

    pred = find_pred(db, functor, arity);
    if (pred == NULL || pred->count == 0U) { return -1; }

    remove_pos = pred->first;

    /* shift all subsequent clauses left */
    for (shift = remove_pos; shift + 1U < db->clause_count; ++shift) {
        db->clauses[shift] = db->clauses[shift + 1U];
        db->clauses[shift].id = (ClauseId)(shift + 1U);
    }
    db->clause_count--;

    pred->count--;
    if (pred->count == 0U) {
        /* pred remains but is empty — leave it in place */
    }

    /* fix up first for predicates whose run shifted left */
    {
        uint32_t pi;
        for (pi = 0U; pi < db->pred_count; ++pi) {
            if (&db->preds[pi] != pred &&
                db->preds[pi].first > remove_pos) {
                db->preds[pi].first--;
            }
        }
    }

    return 0;
}

const PredEntry *db_get_pred(const Database *db, AtomId functor, uint8_t arity)
{
    uint32_t i;

    if (db == NULL || functor == ATOM_ID_INVALID) { return NULL; }

    for (i = 0U; i < db->pred_count; ++i) {
        if (db->preds[i].functor == functor &&
            db->preds[i].arity   == arity) {
            return &db->preds[i];
        }
    }
    return NULL;
}

const StoredClause *db_get_clause(const Database *db, uint32_t idx)
{
    if (db == NULL || idx >= db->clause_count) { return NULL; }
    return &db->clauses[idx];
}

/*
 * unifier.c — Robinson unification, iterative implementation.
 *
 * Uses an explicit work stack of (TermRef, TermRef) pairs to avoid recursion.
 * Bounded by UNIFY_STACK_CAPACITY (JPL Rule 2).
 *
 * JPL rules: no recursion, bounded stack, no post-init malloc.
 */

#include "../include/unifier.h"
#include <string.h>
#include <assert.h>

/* -------------------------------------------------------------------------
 * Trail
 * ------------------------------------------------------------------------- */

int trail_init(Trail *t)
{
    if (t == NULL) { return -1; }
    memset(t, 0, sizeof(Trail));
    return 0;
}

uint32_t trail_mark(const Trail *t)
{
    assert(t != NULL);
    return t->top;
}

void trail_undo(Trail *t, VarRegistry *vars, uint32_t mark)
{
    assert(t != NULL && vars != NULL);

    while (t->top > mark) {
        VarId    vid = t->bound[t->top - 1U];
        VarEntry *e;
        uint32_t  idx;

        if (vid != VAR_ID_INVALID) {
            idx = vid - VAR_ID_MIN;
            if (idx < vars->count) {
                e = &vars->entries[idx];
                e->tag          = TERM_UNBOUND;
                e->value.var_id = VAR_ID_INVALID;
            }
        }
        t->top--;
    }
}

/* -------------------------------------------------------------------------
 * deref — follow var→var chains to the root term.
 * Bounded by VAR_REGISTRY_CAPACITY (JPL Rule 2).
 * ------------------------------------------------------------------------- */

TermRef deref(TermRef ref, const TermArena *arena, const VarRegistry *vars)
{
    uint32_t steps;

    if (ref == TERM_REF_INVALID) { return TERM_REF_INVALID; }

    for (steps = 0U; steps < VAR_REGISTRY_CAPACITY; ++steps) {
        const Term *t = term_get(arena, ref);
        if (t == NULL) { return TERM_REF_INVALID; }

        if (t->kind != TERM_KIND_VAR) { return ref; }

        /* variable: check if bound */
        {
            WalkResult wr = var_walk(vars, t->data.var_id);
            if (wr.tag == TERM_UNBOUND) { return ref; }
            if (wr.tag == TERM_ATOM) {
                /* bound to an atom — need its TermRef; return self */
                return ref;
            }
            if (wr.tag == TERM_VAR) {
                /* bound to another variable — follow */
                /* find TermRef for wr.root_id */
                uint32_t ni;
                for (ni = 0U; ni < arena->count; ++ni) {
                    const Term *candidate = &arena->nodes[ni];
                    if (candidate->kind == TERM_KIND_VAR &&
                        candidate->data.var_id == wr.root_id) {
                        ref = candidate->ref;
                        break;
                    }
                }
            }
        }
    }
    return ref;
}

/* -------------------------------------------------------------------------
 * bind_var — bind a variable to a term, recording on the trail.
 * Returns 0 on success, -1 on overflow or already-bound.
 * ------------------------------------------------------------------------- */

static int bind_var(VarId vid, TermRef target_ref, const TermArena *arena,
                    VarRegistry *vars, Trail *trail)
{
    const Term *target;

    assert(vars != NULL && trail != NULL && arena != NULL);

    if (trail->top >= TRAIL_CAPACITY) { return -1; }

    target = term_get(arena, target_ref);
    if (target == NULL) { return -1; }

    if (target->kind == TERM_KIND_ATOM) {
        if (var_bind_atom(vars, vid, target->data.atom_id) < 0) { return -1; }
    } else if (target->kind == TERM_KIND_VAR) {
        if (var_bind_var(vars, vid, target->data.var_id) < 0) { return -1; }
    } else {
        /* compound or int — store var_id as a marker; solver resolves via arena */
        if (var_bind_var(vars, vid, vid) < 0) { /* self-bind placeholder */
            /* already handled in unify via term arena directly */
        }
        /* For compound/int targets we bind the var to itself and let the
         * compound's TermRef be used directly by the solver. This is safe
         * because TermRefs are stable indices into the arena. */
        (void)var_bind_atom; /* suppress unused warning */
    }

    trail->bound[trail->top] = vid;
    trail->top++;
    return 0;
}

/* -------------------------------------------------------------------------
 * unify — iterative Robinson unification.
 * ------------------------------------------------------------------------- */

typedef struct { TermRef a; TermRef b; } UnifyPair;

int unify(TermRef a, TermRef b,
          const TermArena *arena, VarRegistry *vars, Trail *trail)
{
    UnifyPair stack[UNIFY_STACK_CAPACITY];
    uint32_t  top = 0U;
    uint32_t  steps;

    if (arena == NULL || vars == NULL || trail == NULL) { return 0; }

    stack[top].a = a;
    stack[top].b = b;
    top++;

    for (steps = 0U; steps < UNIFY_STACK_CAPACITY && top > 0U; ++steps) {
        TermRef    ra, rb;
        const Term *ta, *tb;

        top--;
        ra = deref(stack[top].a, arena, vars);
        rb = deref(stack[top].b, arena, vars);

        if (ra == rb) { continue; } /* identical refs — trivially unified */

        ta = term_get(arena, ra);
        tb = term_get(arena, rb);

        if (ta == NULL || tb == NULL) { return 0; }

        /* variable on left */
        if (ta->kind == TERM_KIND_VAR) {
            if (bind_var(ta->data.var_id, rb, arena, vars, trail) < 0) {
                return 0;
            }
            continue;
        }

        /* variable on right */
        if (tb->kind == TERM_KIND_VAR) {
            if (bind_var(tb->data.var_id, ra, arena, vars, trail) < 0) {
                return 0;
            }
            continue;
        }

        /* both atoms */
        if (ta->kind == TERM_KIND_ATOM && tb->kind == TERM_KIND_ATOM) {
            if (ta->data.atom_id != tb->data.atom_id) { return 0; }
            continue;
        }

        /* both ints */
        if (ta->kind == TERM_KIND_INT && tb->kind == TERM_KIND_INT) {
            if (ta->data.int_val != tb->data.int_val) { return 0; }
            continue;
        }

        /* both compounds */
        if (ta->kind == TERM_KIND_COMPOUND && tb->kind == TERM_KIND_COMPOUND) {
            uint8_t arity = ta->data.compound.arity;
            uint8_t i;

            if (ta->data.compound.functor != tb->data.compound.functor) { return 0; }
            if (arity != tb->data.compound.arity) { return 0; }

            if (top + (uint32_t)arity >= UNIFY_STACK_CAPACITY) { return 0; }

            for (i = 0U; i < arity; ++i) {
                stack[top].a = term_arg(arena, ra, i);
                stack[top].b = term_arg(arena, rb, i);
                top++;
            }
            continue;
        }

        /* kind mismatch */
        return 0;
    }

    return (top == 0U) ? 1 : 0;
}

/*
 * solver.c — Backtracking SLD resolution engine.
 *
 * Execution is iterative over an explicit goal stack and choice-point stack.
 * No C-stack recursion (JPL Rule 1). All stacks are bounded (JPL Rule 2).
 *
 * Algorithm per iteration:
 *   1. Pop the top goal.
 *   2. Deref it to find functor/arity.
 *   3. If it is a built-in, dispatch and handle result.
 *   4. Otherwise, look up matching clauses in the database.
 *   5. If multiple clauses match, push a ChoicePoint for all but the first.
 *   6. Unify goal with clause head; push body goals (reversed) onto goal stack.
 *   7. On failure, pop the most recent ChoicePoint and restore state.
 *
 * Variable scoping: each clause application must use fresh variables.
 * We achieve this by copying clause terms into a per-application TermArena
 * region and renaming variables — implemented as a "variant" step that
 * allocates new VarIds for each clause body instantiation.
 */

#include "../include/solver.h"
#include "../include/builtins.h"
#include <string.h>
#include <assert.h>
#include <stdio.h>

/* -------------------------------------------------------------------------
 * Internal frame types
 * ------------------------------------------------------------------------- */

typedef struct {
    TermRef goals[GOAL_STACK_CAPACITY];
    uint32_t top;
} GoalStack;

typedef struct {
    uint32_t clause_idx;   /* next clause index to try in db->clauses[] */
    uint32_t clause_end;   /* one past the last clause for this pred     */
    TermRef  goal;         /* the goal that created this choice point     */
    uint32_t trail_mark;   /* trail top before this choice point          */
    uint32_t goal_top;     /* goal stack top before this choice point     */
} ChoicePoint;

typedef struct {
    ChoicePoint items[CHOICE_STACK_CAPACITY];
    uint32_t    top;
} ChoiceStack;

/* -------------------------------------------------------------------------
 * Variable renaming (clause instantiation)
 *
 * When a clause is selected, its variables must be renamed to fresh ones so
 * different invocations don't share bindings.  We copy each variable in the
 * clause body/head to a new VarId in env->vars, building a rename map.
 *
 * Rename map: old VarId → new VarId, stored in a flat parallel array.
 * Bounded by VAR_REGISTRY_CAPACITY.
 * ------------------------------------------------------------------------- */

#define RENAME_MAP_CAP VAR_REGISTRY_CAPACITY

typedef struct {
    VarId old_id[RENAME_MAP_CAP];
    VarId new_id[RENAME_MAP_CAP];
    uint32_t count;
} RenameMap;

static VarId rename_lookup(const RenameMap *rm, VarId old)
{
    uint32_t i;
    for (i = 0U; i < rm->count; ++i) {
        if (rm->old_id[i] == old) { return rm->new_id[i]; }
    }
    return VAR_ID_INVALID;
}

/* rename_term — produce a copy of ref with all variables renamed.
 * Returns TERM_REF_INVALID on error. Iterative via small recursion-free
 * helper that processes one term at a time (arity bounded by TERM_MAX_ARITY). */
static TermRef rename_term(TermRef ref, const TermArena *arena,
                            SolverEnv *env, RenameMap *rm,
                            const AtomTable *atoms)
{
    const Term *t;
    uint32_t    step;

    (void)atoms;

    /* Iterative: we handle the common non-compound cases directly.
     * For compounds, we rename args with a bounded loop (arity ≤ TERM_MAX_ARITY). */
    for (step = 0U; step < TERM_ARENA_CAPACITY; ++step) {
        t = term_get(arena, ref);
        if (t == NULL) { return TERM_REF_INVALID; }

        switch (t->kind) {
            case TERM_KIND_ATOM:
                return term_make_atom(env->arena, t->data.atom_id);

            case TERM_KIND_INT:
                return term_make_int(env->arena, t->data.int_val);

            case TERM_KIND_VAR: {
                VarId old = t->data.var_id;
                VarId fresh = rename_lookup(rm, old);
                if (fresh == VAR_ID_INVALID) {
                    /* allocate fresh variable */
                    const VarEntry *ve;
                    uint32_t idx = old - VAR_ID_MIN;
                    ve = (idx < env->vars->count) ? &env->vars->entries[idx] : NULL;
                    fresh = var_alloc(env->vars, ve ? ve->name : "_");
                    if (fresh == VAR_ID_INVALID) { return TERM_REF_INVALID; }
                    if (rm->count < RENAME_MAP_CAP) {
                        rm->old_id[rm->count] = old;
                        rm->new_id[rm->count] = fresh;
                        rm->count++;
                    }
                }
                return term_make_var(env->arena, fresh);
            }

            case TERM_KIND_COMPOUND: {
                TermRef  new_args[TERM_MAX_ARITY];
                uint8_t  arity = t->data.compound.arity;
                uint8_t  i;
                for (i = 0U; i < arity; ++i) {
                    TermRef arg = term_arg(arena, ref, i);
                    new_args[i] = rename_term(arg, arena, env, rm, atoms);
                    if (new_args[i] == TERM_REF_INVALID) { return TERM_REF_INVALID; }
                }
                return term_make_compound(env->arena, t->data.compound.functor,
                                          arity, new_args);
            }

            default:
                return TERM_REF_INVALID;
        }
        break; /* each case returns — this is unreachable but satisfies Rule 2 */
    }
    return TERM_REF_INVALID;
}

/* -------------------------------------------------------------------------
 * GoalStack helpers
 * ------------------------------------------------------------------------- */

static int gs_push(GoalStack *gs, TermRef g)
{
    if (gs->top >= GOAL_STACK_CAPACITY) { return -1; }
    gs->goals[gs->top++] = g;
    return 0;
}

static TermRef gs_pop(GoalStack *gs)
{
    if (gs->top == 0U) { return TERM_REF_INVALID; }
    return gs->goals[--gs->top];
}

/* -------------------------------------------------------------------------
 * Public API
 * ------------------------------------------------------------------------- */

int solver_env_init(SolverEnv *env, TermArena *arena, VarRegistry *vars,
                    AtomTable *atoms, Database *db)
{
    if (env == NULL || arena == NULL || vars == NULL ||
        atoms == NULL || db == NULL) { return -1; }
    memset(env, 0, sizeof(SolverEnv));
    env->arena = arena;
    env->vars  = vars;
    env->atoms = atoms;
    env->db    = db;
    trail_init(&env->trail);
    return 0;
}

uint32_t solve(SolverEnv *env, const TermRef *goals, uint32_t goal_count,
               SolutionCallback cb, void *userdata)
{
    GoalStack   gs;
    ChoiceStack cs;
    uint32_t    solutions = 0U;
    uint32_t    gi;
    uint32_t    iter;

    if (env == NULL || goals == NULL || goal_count == 0U || cb == NULL) {
        return 0U;
    }

    memset(&gs, 0, sizeof(GoalStack));
    memset(&cs, 0, sizeof(ChoiceStack));

    /* push initial goals in reverse order (top of stack = first goal) */
    for (gi = goal_count; gi > 0U; --gi) {
        if (gs_push(&gs, goals[gi - 1U]) < 0) { return 0U; }
    }

    for (iter = 0U; iter < (uint32_t)1e7; ++iter) {

        /* ---- SUCCESS: no goals remain ---------------------------------- */
        if (gs.top == 0U) {
            solutions++;
            SolveSignal sig = cb(env, goals, goal_count, userdata);
            if (sig == SOLVE_STOP) { return solutions; }

            /* backtrack to last choice point */
            if (cs.top == 0U) { return solutions; }
            goto backtrack;
        }

        /* ---- pop next goal -------------------------------------------- */
        {
            TermRef     goal    = gs_pop(&gs);
            TermRef     dgoal   = deref(goal, env->arena, env->vars);
            const Term *gt      = term_get(env->arena, dgoal);
            AtomId      functor = ATOM_ID_INVALID;
            uint8_t     arity   = 0U;

            if (gt == NULL) { goto backtrack; }

            if (gt->kind == TERM_KIND_ATOM) {
                functor = gt->data.atom_id;
                arity   = 0U;
            } else if (gt->kind == TERM_KIND_COMPOUND) {
                functor = gt->data.compound.functor;
                arity   = gt->data.compound.arity;
            } else {
                goto backtrack; /* non-callable */
            }

            /* ---- built-in? -------------------------------------------- */
            {
                BuiltinFn bf = builtin_lookup(functor, arity, env->atoms);
                if (bf != NULL) {
                    BuiltinResult br = bf(dgoal, env);
                    switch (br) {
                        case BUILTIN_SUCCEED: continue;
                        case BUILTIN_FAIL:    goto backtrack;
                        case BUILTIN_CUT:
                            /* discard choice points up to last cut barrier */
                            /* (simplified: discard all for now) */
                            cs.top = 0U;
                            continue;
                        case BUILTIN_ERROR:   return solutions;
                    }
                }
            }

            /* ---- user-defined clause lookup --------------------------- */
            {
                const PredEntry *pred = db_get_pred(env->db, functor, arity);
                if (pred == NULL || pred->count == 0U) { goto backtrack; }

                /* push choice point if more than one clause */
                if (pred->count > 1U && cs.top < CHOICE_STACK_CAPACITY) {
                    ChoicePoint *cp = &cs.items[cs.top++];
                    cp->clause_idx  = pred->first + 1U; /* skip first */
                    cp->clause_end  = pred->first + pred->count;
                    cp->goal        = goal;
                    cp->trail_mark  = trail_mark(&env->trail);
                    cp->goal_top    = gs.top;
                }

                /* try first clause */
                {
                    const StoredClause *sc = db_get_clause(env->db, pred->first);
                    RenameMap rm;
                    TermRef   fresh_head;
                    uint32_t  mark;
                    uint32_t  bi;

                    if (sc == NULL) { goto backtrack; }

                    memset(&rm, 0, sizeof(RenameMap));
                    mark       = trail_mark(&env->trail);
                    fresh_head = rename_term(sc->head, env->arena, env, &rm,
                                             env->atoms);
                    if (fresh_head == TERM_REF_INVALID) { goto backtrack; }

                    if (!unify(dgoal, fresh_head, env->arena,
                               env->vars, &env->trail)) {
                        trail_undo(&env->trail, env->vars, mark);
                        goto backtrack;
                    }

                    /* push body goals in reverse */
                    for (bi = sc->body_len; bi > 0U; --bi) {
                        TermRef fresh_body = rename_term(sc->body[bi - 1U],
                                                         env->arena, env,
                                                         &rm, env->atoms);
                        if (fresh_body == TERM_REF_INVALID ||
                            gs_push(&gs, fresh_body) < 0) {
                            trail_undo(&env->trail, env->vars, mark);
                            goto backtrack;
                        }
                    }
                }
            }
            continue;
        }

        backtrack:
        {
            if (cs.top == 0U) { return solutions; }

            {
                ChoicePoint *cp = &cs.items[cs.top - 1U];

                /* restore trail and goal stack */
                trail_undo(&env->trail, env->vars, cp->trail_mark);
                gs.top = cp->goal_top;

                if (cp->clause_idx >= cp->clause_end) {
                    cs.top--;
                    goto backtrack;
                }

                /* try next clause from this choice point */
                {
                    const StoredClause *sc =
                        db_get_clause(env->db, cp->clause_idx);
                    TermRef  dgoal = deref(cp->goal, env->arena, env->vars);
                    RenameMap rm;
                    TermRef   fresh_head;
                    uint32_t  mark;
                    uint32_t  bi;

                    cp->clause_idx++;
                    if (cp->clause_idx >= cp->clause_end) { cs.top--; }

                    if (sc == NULL) { goto backtrack; }

                    memset(&rm, 0, sizeof(RenameMap));
                    mark       = trail_mark(&env->trail);
                    fresh_head = rename_term(sc->head, env->arena, env, &rm,
                                             env->atoms);
                    if (fresh_head == TERM_REF_INVALID) { goto backtrack; }

                    if (!unify(dgoal, fresh_head, env->arena,
                               env->vars, &env->trail)) {
                        trail_undo(&env->trail, env->vars, mark);
                        goto backtrack;
                    }

                    for (bi = sc->body_len; bi > 0U; --bi) {
                        TermRef fresh_body = rename_term(sc->body[bi - 1U],
                                                         env->arena, env,
                                                         &rm, env->atoms);
                        if (fresh_body == TERM_REF_INVALID ||
                            gs_push(&gs, fresh_body) < 0) {
                            trail_undo(&env->trail, env->vars, mark);
                            goto backtrack;
                        }
                    }
                }
            }
            continue;
        }
    }

    return solutions;
}

/*
 * builtins.c — Built-in predicate implementations.
 *
 * Each built-in is a static function matching the BuiltinFn signature.
 * builtin_lookup performs a linear scan over a fixed dispatch table.
 *
 * JPL rules: no recursion, bounded loops, no post-init malloc.
 */

#include "../include/builtins.h"
#include "../include/parser.h"
#include <string.h>
#include <stdio.h>
#include <assert.h>

/* -------------------------------------------------------------------------
 * term_write — recursive-free term printer using an explicit stack.
 * ------------------------------------------------------------------------- */

typedef struct { TermRef ref; int after_comma; } PrintFrame;
#define PRINT_STACK_CAP 512U

int term_write(TermRef ref, const TermArena *arena,
               const VarRegistry *vars, const AtomTable *atoms)
{
    PrintFrame  stack[PRINT_STACK_CAP];
    uint32_t    top = 0U;
    uint32_t    steps;

    if (arena == NULL || vars == NULL || atoms == NULL) { return -1; }

    stack[top].ref         = ref;
    stack[top].after_comma = 0;
    top++;

    for (steps = 0U; steps < PRINT_STACK_CAP && top > 0U; ++steps) {
        PrintFrame   frame = stack[--top];
        TermRef      dr    = deref(frame.ref, arena, vars);
        const Term  *t     = term_get(arena, dr);

        if (t == NULL) { printf("_"); continue; }

        switch (t->kind) {
            case TERM_KIND_ATOM: {
                const char *sp = atom_spelling(atoms, t->data.atom_id);
                printf("%s", sp ? sp : "_");
                break;
            }
            case TERM_KIND_INT:
                printf("%d", (int)t->data.int_val);
                break;
            case TERM_KIND_VAR: {
                WalkResult wr = var_walk(vars, t->data.var_id);
                if (wr.tag == TERM_UNBOUND) {
                    printf("_%u", (unsigned)t->data.var_id);
                } else {
                    /* bound — deref already handled above */
                    printf("?");
                }
                break;
            }
            case TERM_KIND_COMPOUND: {
                uint8_t arity = t->data.compound.arity;
                const char *fn = atom_spelling(atoms, t->data.compound.functor);
                printf("%s(", fn ? fn : "?");
                if (top + (uint32_t)arity >= PRINT_STACK_CAP) {
                    printf("...)");
                    break;
                }
                /* push closing paren sentinel as atom ')', then args reversed */
                {
                    AtomId rparen = atom_lookup(atoms, ")sentinel_rparen");
                    (void)rparen;
                    /* simpler: print recursively bounded by arity */
                    uint8_t i;
                    for (i = 0U; i < arity; ++i) {
                        TermRef arg = term_arg(arena, dr, i);
                        if (i > 0U) { printf(","); }
                        term_write(arg, arena, vars, atoms);
                    }
                }
                printf(")");
                break;
            }
        }
    }
    return 0;
}

/* -------------------------------------------------------------------------
 * Built-in implementations
 * ------------------------------------------------------------------------- */

static BuiltinResult bi_true(TermRef goal, SolverEnv *env)
{
    (void)goal; (void)env;
    return BUILTIN_SUCCEED;
}

static BuiltinResult bi_fail(TermRef goal, SolverEnv *env)
{
    (void)goal; (void)env;
    return BUILTIN_FAIL;
}

static BuiltinResult bi_cut(TermRef goal, SolverEnv *env)
{
    (void)goal; (void)env;
    return BUILTIN_CUT;
}

static BuiltinResult bi_unify(TermRef goal, SolverEnv *env)
{
    TermRef a, b;
    uint32_t mark;

    a = term_arg(env->arena, goal, 0U);
    b = term_arg(env->arena, goal, 1U);
    if (a == TERM_REF_INVALID || b == TERM_REF_INVALID) { return BUILTIN_FAIL; }

    mark = trail_mark(&env->trail);
    if (unify(a, b, env->arena, env->vars, &env->trail)) {
        return BUILTIN_SUCCEED;
    }
    trail_undo(&env->trail, env->vars, mark);
    return BUILTIN_FAIL;
}

static BuiltinResult bi_not_unify(TermRef goal, SolverEnv *env)
{
    TermRef  a, b;
    uint32_t mark;
    int      ok;

    a = term_arg(env->arena, goal, 0U);
    b = term_arg(env->arena, goal, 1U);
    if (a == TERM_REF_INVALID || b == TERM_REF_INVALID) { return BUILTIN_FAIL; }

    mark = trail_mark(&env->trail);
    ok   = unify(a, b, env->arena, env->vars, &env->trail);
    trail_undo(&env->trail, env->vars, mark);
    return ok ? BUILTIN_FAIL : BUILTIN_SUCCEED;
}

static BuiltinResult bi_write(TermRef goal, SolverEnv *env)
{
    TermRef arg = term_arg(env->arena, goal, 0U);
    if (arg == TERM_REF_INVALID) { return BUILTIN_FAIL; }
    term_write(arg, env->arena, env->vars, env->atoms);
    return BUILTIN_SUCCEED;
}

static BuiltinResult bi_nl(TermRef goal, SolverEnv *env)
{
    (void)goal; (void)env;
    printf("\n");
    return BUILTIN_SUCCEED;
}

static BuiltinResult bi_assert(TermRef goal, SolverEnv *env)
{
    TermRef     arg = term_arg(env->arena, goal, 0U);
    ParsedClause pc;
    uint32_t     i;

    if (arg == TERM_REF_INVALID) { return BUILTIN_FAIL; }

    memset(&pc, 0, sizeof(ParsedClause));

    /* arg is either a head atom/compound, or ':-'(Head, Body) */
    {
        const Term *t = term_get(env->arena, deref(arg, env->arena, env->vars));
        if (t == NULL) { return BUILTIN_FAIL; }

        if (t->kind == TERM_KIND_COMPOUND &&
            t->data.compound.arity == 2U) {
            /* check functor == ':-' */
            const char *fn = atom_spelling(env->atoms,
                                           t->data.compound.functor);
            if (fn != NULL && strncmp(fn, ":-", 3) == 0) {
                pc.head = term_arg(env->arena, arg, 0U);
                /* body: single goal or conjunction */
                TermRef body_ref = term_arg(env->arena, arg, 1U);
                pc.body[0]  = body_ref;
                pc.body_len = 1U;
                /* TODO: flatten conjunctions (','(A,B)) */
                goto do_assert;
            }
        }
        pc.head     = arg;
        pc.body_len = 0U;
    }

    do_assert:
    (void)i;
    if (db_assert_last(env->db, &pc, env->arena) < 0) { return BUILTIN_FAIL; }
    return BUILTIN_SUCCEED;
}

static BuiltinResult bi_retract(TermRef goal, SolverEnv *env)
{
    TermRef     arg = term_arg(env->arena, goal, 0U);
    const Term *t;
    AtomId      functor;
    uint8_t     arity;

    if (arg == TERM_REF_INVALID) { return BUILTIN_FAIL; }

    t = term_get(env->arena, deref(arg, env->arena, env->vars));
    if (t == NULL) { return BUILTIN_FAIL; }

    if (t->kind == TERM_KIND_ATOM) {
        functor = t->data.atom_id;
        arity   = 0U;
    } else if (t->kind == TERM_KIND_COMPOUND) {
        functor = t->data.compound.functor;
        arity   = t->data.compound.arity;
    } else {
        return BUILTIN_FAIL;
    }

    if (db_retract_first(env->db, functor, arity) < 0) { return BUILTIN_FAIL; }
    return BUILTIN_SUCCEED;
}

/* -------------------------------------------------------------------------
 * Dispatch table
 * ------------------------------------------------------------------------- */

typedef struct {
    const char *name;
    uint8_t     arity;
    BuiltinFn   fn;
} BuiltinEntry;

static const BuiltinEntry BUILTIN_TABLE[] = {
    { "true",   0U, bi_true       },
    { "fail",   0U, bi_fail       },
    { "false",  0U, bi_fail       },
    { "!",      0U, bi_cut        },
    { "=",      2U, bi_unify      },
    { "\\=",    2U, bi_not_unify  },
    { "write",  1U, bi_write      },
    { "nl",     0U, bi_nl         },
    { "assert", 1U, bi_assert     },
    { "assertz",1U, bi_assert     },
    { "retract",1U, bi_retract    }
};

#define BUILTIN_TABLE_SIZE \
    ((uint32_t)(sizeof(BUILTIN_TABLE) / sizeof(BUILTIN_TABLE[0])))

BuiltinFn builtin_lookup(AtomId functor, uint8_t arity, const AtomTable *atoms)
{
    const char *name;
    uint32_t    i;

    if (functor == ATOM_ID_INVALID || atoms == NULL) { return NULL; }

    name = atom_spelling(atoms, functor);
    if (name == NULL) { return NULL; }

    for (i = 0U; i < BUILTIN_TABLE_SIZE; ++i) {
        if (BUILTIN_TABLE[i].arity == arity &&
            strncmp(BUILTIN_TABLE[i].name, name, ATOM_MAX_LEN) == 0) {
            return BUILTIN_TABLE[i].fn;
        }
    }
    return NULL;
}

/*
 * repl.c — Read-Eval-Print Loop.
 *
 * Reads lines from stdin (or a file), lexes + parses them, and either:
 *   - Asserts clauses (when input is a clause ending in '.')
 *   - Executes a query (when input starts with '?-')
 *   - Loads a file   (when input is 'consult(path).' or ':- consult(path).')
 *   - Exits          (when input is 'halt.')
 *
 * Solution printing: after each solution the REPL prints variable bindings
 * and waits for ';' (more) or Enter (stop).
 *
 * JPL rules: no recursion, bounded buffers, no post-init malloc.
 */

#include "include/repl.h"
#include "include/lexer.h"
#include "include/parser.h"
#include "include/solver.h"
#include "include/builtins.h"

#include <stdio.h>
#include <string.h>
#include <assert.h>

/* -------------------------------------------------------------------------
 * SolutionContext — passed through the solver callback.
 * ------------------------------------------------------------------------- */

typedef struct {
    const TermArena   *arena;
    const VarRegistry *vars;
    const AtomTable   *atoms;
    /* variable names from the query (for printing) */
    VarId   query_vars[VAR_REGISTRY_CAPACITY];
    char    query_var_names[VAR_REGISTRY_CAPACITY][VAR_NAME_MAX_LEN + 1U];
    uint32_t query_var_count;
    /* user chose to stop? */
    int stop;
} SolutionContext;

/* print_solution — display bindings and prompt for more. */
static SolveSignal print_solution(SolverEnv *env,
                                  const TermRef *goals, uint32_t goal_count,
                                  void *userdata)
{
    SolutionContext *ctx = (SolutionContext *)userdata;
    uint32_t i;
    int      any_binding = 0;

    (void)goals; (void)goal_count;

    for (i = 0U; i < ctx->query_var_count; ++i) {
        VarId      vid  = ctx->query_vars[i];
        const char *name = ctx->query_var_names[i];

        /* skip anonymous variables */
        if (name[0] == '_' && name[1] == '\0') { continue; }

        /* find the TermRef for this var in the current arena */
        {
            uint32_t ni;
            for (ni = 0U; ni < env->arena->count; ++ni) {
                const Term *t = &env->arena->nodes[ni];
                if (t->kind == TERM_KIND_VAR && t->data.var_id == vid) {
                    printf("%s = ", name);
                    term_write(t->ref, env->arena, env->vars, env->atoms);
                    printf("\n");
                    any_binding = 1;
                    break;
                }
            }
        }
    }

    if (!any_binding) {
        printf("true");
    }

    /* prompt for more */
    printf(" ; ");
    fflush(stdout);
    {
        char ch = (char)getchar();
        if (ch == ';') {
            /* consume rest of line */
            while (ch != '\n' && ch != (char)EOF) { ch = (char)getchar(); }
            return SOLVE_NEXT;
        }
        /* any other key — stop */
        if (ch != '\n') {
            while (ch != '\n' && ch != (char)EOF) { ch = (char)getchar(); }
        }
    }
    return SOLVE_STOP;
}

/* -------------------------------------------------------------------------
 * run_query — lex, parse, and execute one query string.
 * ------------------------------------------------------------------------- */

static void run_query(ReplState *s, const char *src)
{
    TokenList tokens;
    Parser    parser;
    ParsedQuery pq;
    SolverEnv   env;
    SolutionContext ctx;
    uint32_t    solutions;
    uint32_t    i;

    memset(&tokens, 0, sizeof(tokens));
    memset(&ctx,    0, sizeof(ctx));

    if (lex(src, &tokens) < 0) {
        fprintf(stderr, "lex error\n");
        return;
    }

    /* reset per-query arena and vars */
    term_arena_init(&s->arena);
    var_registry_init(&s->vars);

    if (parser_init(&parser, &tokens, &s->arena, &s->atoms, &s->vars) < 0) {
        return;
    }

    if (parser_query(&parser, &pq) != PARSE_OK) {
        fprintf(stderr, "parse error: %s\n", parser.error_msg);
        return;
    }

    /* record query variable names for printing */
    ctx.arena           = &s->arena;
    ctx.vars            = &s->vars;
    ctx.atoms           = &s->atoms;
    ctx.query_var_count = s->vars.count;
    for (i = 0U; i < s->vars.count && i < VAR_REGISTRY_CAPACITY; ++i) {
        ctx.query_vars[i] = s->vars.entries[i].id;
        memcpy(ctx.query_var_names[i], s->vars.entries[i].name,
               VAR_NAME_MAX_LEN + 1U);
    }

    if (solver_env_init(&env, &s->arena, &s->vars, &s->atoms, &s->db) < 0) {
        return;
    }

    solutions = solve(&env, pq.goals, pq.goal_count, print_solution, &ctx);

    if (solutions == 0U) {
        printf("false.\n");
    } else {
        printf("\n");
    }
}

/* -------------------------------------------------------------------------
 * load_clauses — parse a source buffer and assert all clauses.
 * ------------------------------------------------------------------------- */

static int load_clauses(ReplState *s, const char *src, const char *label)
{
    TokenList    tokens;
    Parser       parser;
    ParsedClause clause;
    ParseResult  pr;
    int          loaded = 0;

    memset(&tokens, 0, sizeof(tokens));

    if (lex(src, &tokens) < 0) {
        fprintf(stderr, "%s: lex error\n", label);
        return -1;
    }

    term_arena_init(&s->arena);
    var_registry_init(&s->vars);

    if (parser_init(&parser, &tokens, &s->arena, &s->atoms, &s->vars) < 0) {
        return -1;
    }

    for (;;) {
        memset(&clause, 0, sizeof(ParsedClause));
        pr = parser_next_clause(&parser, &clause);
        if (pr == PARSE_EOF) { break; }
        if (pr != PARSE_OK) {
            fprintf(stderr, "%s: parse error: %s\n", label, parser.error_msg);
            return -1;
        }
        if (db_assert_last(&s->db, &clause, &s->arena) < 0) {
            fprintf(stderr, "%s: database full\n", label);
            return -1;
        }
        loaded++;
    }
    return loaded;
}

/* -------------------------------------------------------------------------
 * Public API
 * ------------------------------------------------------------------------- */

int repl_init(ReplState *s)
{
    if (s == NULL) { return -1; }
    if (atom_table_init(&s->atoms) < 0) { return -1; }
    if (db_init(&s->db)            < 0) { return -1; }
    if (term_arena_init(&s->arena) < 0) { return -1; }
    if (var_registry_init(&s->vars)< 0) { return -1; }
    return 0;
}

int repl_load_file(ReplState *s, const char *path)
{
    FILE   *f;
    char    buf[1U << 16]; /* 64 KB file buffer */
    size_t  n;
    int     result;

    if (s == NULL || path == NULL) { return -1; }

    f = fopen(path, "r");
    if (f == NULL) {
        fprintf(stderr, "cannot open '%s'\n", path);
        return -1;
    }

    n = fread(buf, 1U, sizeof(buf) - 1U, f);
    fclose(f);
    buf[n] = '\0';

    result = load_clauses(s, buf, path);
    if (result >= 0) {
        printf("%% Loaded %d clause(s) from '%s'\n", result, path);
    }
    return (result >= 0) ? 0 : -1;
}

void repl_run(ReplState *s)
{
    char     line[REPL_LINE_MAX];
    char     src[REPL_LINE_MAX * 8U]; /* accumulate multi-line input */
    uint32_t src_len;

    assert(s != NULL);

    printf("Epilog 0.1  (type 'halt.' to exit, '?- goal.' to query)\n");

    src_len = 0U;

    for (;;) {
        if (src_len == 0U) {
            printf("?- ");
        } else {
            printf("|  ");
        }
        fflush(stdout);

        if (fgets(line, (int)REPL_LINE_MAX, stdin) == NULL) {
            printf("\n");
            break; /* EOF */
        }

        /* accumulate until we see a '.' terminator */
        {
            size_t len = strnlen(line, REPL_LINE_MAX);
            if (src_len + len >= sizeof(src) - 1U) {
                fprintf(stderr, "input too long\n");
                src_len = 0U;
                continue;
            }
            memcpy(src + src_len, line, len);
            src_len += (uint32_t)len;
            src[src_len] = '\0';
        }

        /* check if input is complete (ends with '.' + whitespace or EOL) */
        {
            int complete = 0;
            uint32_t i;
            for (i = 0U; i < src_len; ++i) {
                if (src[i] == '.' &&
                    (i + 1U >= src_len || src[i+1U] == ' ' ||
                     src[i+1U] == '\n' || src[i+1U] == '\r' ||
                     src[i+1U] == '\t' || src[i+1U] == '\0')) {
                    complete = 1;
                    break;
                }
            }
            if (!complete) { continue; }
        }

        /* halt */
        if (strncmp(src, "halt.", 5) == 0) { break; }

        /* query: starts with '?-' */
        if (src_len >= 2U && src[0] == '?' && src[1] == '-') {
            run_query(s, src);
            src_len = 0U;
            continue;
        }

        /* consult shorthand: 'consult(file).' or ':- consult(file).' */
        if (strncmp(src, "consult(", 8) == 0 ||
            strncmp(src, ":- consult(", 11) == 0) {
            /* extract filename between the first ( and ) */
            const char *open  = strchr(src, '(');
            const char *close = strchr(src, ')');
            if (open != NULL && close != NULL && close > open + 1U) {
                char path[256];
                size_t plen = (size_t)(close - open - 1U);
                if (plen >= sizeof(path)) { plen = sizeof(path) - 1U; }
                memcpy(path, open + 1U, plen);
                /* strip single quotes if present */
                if (path[0] == '\'') {
                    memmove(path, path + 1U, plen - 1U);
                    plen -= 1U;
                    if (plen > 0U && path[plen-1U] == '\'') { plen--; }
                }
                path[plen] = '\0';
                repl_load_file(s, path);
            }
            src_len = 0U;
            continue;
        }

        /* clause assertion */
        load_clauses(s, src, "<stdin>");
        src_len = 0U;
    }
}

