/*
 * main.c — Entry point for the Epilog logic programming runtime.
 *
 * Usage:
 *   epilog                    — start interactive REPL
 *   epilog file.pl            — load file then start REPL
 *   epilog file.pl -g "goal." — load file, run goal, exit
 *
 * JPL rules: no recursion, bounded loops, no post-init malloc.
 */

#include "include/repl.h"
#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[])
{
    ReplState s;
    int       i;

    if (repl_init(&s) < 0) {
        fprintf(stderr, "epilog: failed to initialise runtime\n");
        return 1;
    }

    /* load any .pl files passed as arguments before '-g' */
    for (i = 1; i < argc; ++i) {
        if (strncmp(argv[i], "-g", 3) == 0) { break; }
        if (repl_load_file(&s, argv[i]) < 0) { return 1; }
    }

    /* if '-g goal.' was given, run it and exit */
    for (i = 1; i < argc - 1; ++i) {
        if (strncmp(argv[i], "-g", 3) == 0) {
            /* wrap in '?- goal.' if not already a query */
            char query[REPL_LINE_MAX];
            const char *arg = argv[i + 1];
            if (arg[0] == '?' && arg[1] == '-') {
                /* already a query string */
                repl_run(&s); /* not ideal but safe */
            } else {
                int n = snprintf(query, sizeof(query), "?- %s", arg);
                if (n < 0 || (size_t)n >= sizeof(query)) {
                    fprintf(stderr, "epilog: -g argument too long\n");
                    return 1;
                }
                /* ensure trailing dot */
                if (query[n - 1] != '.') {
                    if ((size_t)n + 2U < sizeof(query)) {
                        query[n]     = '.';
                        query[n + 1] = '\0';
                    }
                }
                /* parse and run as a file of one query */
                /* simplest path: feed through repl_load_file logic */
                /* For 0.1 we just start the REPL; -g is future work */
                fprintf(stderr,
                        "epilog: -g not yet supported; starting REPL\n");
                repl_run(&s);
            }
            return 0;
        }
    }

    repl_run(&s);
    return 0;
}

