/*
 * main.c — Entry point for the Epilog logic programming runtime.
 *
 * Usage:
 *   epilog [--verbose|-v] [file.pl ...]
 *
 * JPL rules: no recursion, bounded loops, no post-init malloc.
 */

#include "include/repl.h"
#include "include/log.h"
#include <stdio.h>
#include <string.h>

int g_verbose = 0;  /* definition; declared extern in log.h */

int main(int argc, char *argv[])
{
    static ReplState s;  /* too large for the stack (~8 MB) */
    int              i;

    LOG_INIT(argc, argv);

    if (repl_init(&s) < 0) {
        fprintf(stderr, "epilog: failed to initialise runtime\n");
        return 1;
    }

    VLOG("runtime initialised");

    /* load any .pl files passed as arguments (skip flags) */
    for (i = 1; i < argc; ++i) {
        if (strncmp(argv[i], "--verbose", 10) == 0) { continue; }
        if (strncmp(argv[i], "-v",         3) == 0) { continue; }
        if (argv[i][0] == '-') { continue; }
        VLOG("loading file: %s", argv[i]);
        if (repl_load_file(&s, argv[i]) < 0) { return 1; }
    }

    repl_run(&s);
    return 0;
}
